public class Complex_divide_TriageGen0Test {

    private static final double EPSILON = 1e-10;

    @Test
    public void testDivide_NormalValues() {
        Complex c = new Complex(10.0, 5.0);
        Complex result = c.divide(2.0);
        assertEquals(5.0, result.getReal(), EPSILON);
        assertEquals(2.5, result.getImaginary(), EPSILON);
    }














}

